 41	    /**
 42	     * 단일 사용자 알림 생성
 43	     */
 44	    public NotificationDTO createNotification(Long userId, NotificationCategory category, NotificationType type, String message) {
 45	        try {
 46	            User user = userRepository.findById(userId)
 47	                    .orElseThrow(() -> new NotificationException(
 48	                            NotificationErrorCode.NOTIFICATION_USER_NOT_FOUND,
 49	                            "사용자 ID: " + userId + "를 찾을 수 없습니다."
 50	                    ));
 51	
 52	            Notification notification = buildNotification(user, category, type, message);
 53	            Notification savedNotification = notificationRepository.save(notification);
 54	            log.info("알림 생성 완료: 사용자={}, 카테고리={}, 타입={}", user.getEmail(), category, type);
 55	
 56	            // 실시간 알림 전송 시도
 57	            sendRealTimeNotification(user.getEmail(), toDTO(savedNotification));
 58	
 59	            return toDTO(savedNotification);
 60	        } catch (NotificationException e) {
 61	            throw e; // 이미 NotificationException이면 그대로 전파
 62	        } catch (Exception e) {
 63	            log.error("알림 생성 중 오류 발생: 사용자ID={}, 카테고리={}, 타입={}, 오류={}",
 64	                    userId, category, type, e.getMessage(), e);
 65	            throw new NotificationException(NotificationErrorCode.NOTIFICATION_CREATION_FAILED, e);
 66	        }
 67	    }
